-- Seed 20 Realistic Students with Applications, Payments, and Allocations
-- Run this in phpMyAdmin or MySQL CLI to populate multiple pages of student data

ON DUPLICATE KEY UPDATE full_name=VALUES(full_name), form_no=VALUES(form_no);

-- Applications for multiple students
ON DUPLICATE KEY UPDATE status=VALUES(status);

-- Allocations
ON DUPLICATE KEY UPDATE status=VALUES(status);

-- Update occupied count on rooms
UPDATE rooms r SET occupied = (
    SELECT COUNT(*) FROM allocations a WHERE a.room_id = r.room_id AND a.status = 'Active'
);
